<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Traffic History - <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?> - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=8"><link rel="stylesheet" href="../assets/css/common.css?v=8"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe.css?v=14"><style>
body{margin:0}.history-page{padding:22px;max-width:1200px;margin:0 auto}.history-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.history-title{font-size:22px;font-weight:800;color:var(--text);margin:0}.history-sub{font-size:11px;color:var(--muted);margin-top:4px}.history-card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:16px;box-shadow:var(--shadow-card,0 2px 10px rgba(0,0,0,.04));margin-bottom:12px}.ranges{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.range{border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:7px;padding:7px 12px;font-size:11px;cursor:pointer}.range.active{background:var(--primary);border-color:var(--primary);color:#fff}.chart-wrap{height:340px}.chart{width:100%;height:100%;display:block}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:12px}.kpi{border:1px solid var(--border);border-radius:9px;padding:10px}.kpi b{display:block;color:var(--text);font-size:15px;white-space:nowrap}.kpi span{font-size:8px;color:var(--muted)}.section-title{font-size:13px;font-weight:800;color:var(--text);margin:0 0 10px}.detail-wrap{overflow:auto}.detail-table{width:100%;border-collapse:collapse;font-size:10px}.detail-table th,.detail-table td{padding:8px 9px;border-bottom:1px solid var(--border);text-align:right;white-space:nowrap}.detail-table th:first-child,.detail-table td:first-child{text-align:left}.detail-table th{color:var(--muted);font-size:9px;text-transform:uppercase}.back{display:inline-flex;align-items:center;text-decoration:none}.badge-live{display:inline-flex;align-items:center;gap:5px;margin-left:8px;padding:4px 7px;border-radius:999px;background:#ecfdf5;color:#047857;font-size:9px;font-weight:700}.dot{width:6px;height:6px;border-radius:50%;background:#10b981}@media(max-width:1000px){.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.history-page{padding:12px}.chart-wrap{height:260px}.kpis{grid-template-columns:1fr 1fr}.history-head{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="history-page"><div class="history-head"><div><h1 class="history-title">Traffic History — <?=htmlspecialchars($username,ENT_QUOTES,'UTF-8')?></h1><div id="meta" class="history-sub">Memuat data...</div></div><div><span id="live" class="badge-live"><i class="dot"></i>Auto refresh 10s</span> <a class="btn btn-secondary back" href="./">← Kembali PPPoE</a></div></div><section class="history-card"><div class="ranges"><button class="range" data-range="1h">1 Jam</button><button class="range" data-range="6h">6 Jam</button><button class="range active" data-range="24h">24 Jam</button><button class="range" data-range="7d">7 Hari</button><button class="range" data-range="30d">30 Hari</button></div><div class="chart-wrap"><canvas id="chart" class="chart"></canvas></div><div class="kpis"><div class="kpi"><b id="rx">0 B</b><span>RX TERAKHIR</span></div><div class="kpi"><b id="tx">0 B</b><span>TX TERAKHIR</span></div><div class="kpi"><b id="avgRx">0 bps</b><span>AVG DOWNLOAD</span></div><div class="kpi"><b id="avgTx">0 bps</b><span>AVG UPLOAD</span></div><div class="kpi"><b id="peakRx">0 bps</b><span>PEAK DOWNLOAD</span></div><div class="kpi"><b id="peakTx">0 bps</b><span>PEAK UPLOAD</span></div></div></section><section class="history-card"><h2 class="section-title">Detail Traffic</h2><div class="detail-wrap"><table class="detail-table"><thead><tr><th>Waktu</th><th>RX Cumulative</th><th>TX Cumulative</th><th>Download</th><th>Upload</th></tr></thead><tbody id="details"><tr><td colspan="5">Memuat...</td></tr></tbody></table></div></section></main><script>
const user=<?=json_encode($username,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,api='../api/pppoe_history.php';const $=id=>document.getElementById(id);let currentRange='24h';
function bytes(n){n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';const u=['KB','MB','GB','TB'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}
function speed(n){n=Number(n)||0;if(n<1000)return n.toFixed(0)+' bps';const u=['Kbps','Mbps','Gbps','Tbps'];let i=-1;do{n/=1000;i++}while(n>=1000&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}
function draw(d){const c=$('chart'),r=c.getBoundingClientRect(),ratio=devicePixelRatio||1,w=Math.max(320,r.width),h=Math.max(180,r.height);c.width=w*ratio;c.height=h*ratio;const x=c.getContext('2d');x.setTransform(ratio,0,0,ratio,0,0);x.clearRect(0,0,w,h);const vals=[...(d.rx_speed||[]),...(d.tx_speed||[])].map(Number),max=Math.max(...vals,1),left=58,right=18,top=18,bottom=34,pw=w-left-right,ph=h-top-bottom,cs=getComputedStyle(document.body),muted=cs.getPropertyValue('--muted')||'#64748b',border=cs.getPropertyValue('--border')||'#e2e8f0',primary=cs.getPropertyValue('--primary')||'#2563eb';x.font='9px sans-serif';x.fillStyle=muted;x.strokeStyle=border;for(let i=0;i<=4;i++){let y=top+ph*i/4;x.beginPath();x.moveTo(left,y);x.lineTo(left+pw,y);x.stroke();x.fillText(speed(max*(1-i/4)),4,y+3)}function line(a,dash){if(!a.length)return;x.beginPath();a.forEach((v,i)=>{let px=left+(a.length<2?0:pw*i/(a.length-1)),py=top+ph-(Number(v)/max)*ph;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle=primary;x.lineWidth=2;x.setLineDash(dash?[5,4]:[]);x.stroke();x.setLineDash([])}line(d.rx_speed||[],false);line(d.tx_speed||[],true);x.fillStyle=muted;x.fillText('RX Download —',left,h-10);x.fillText('TX Upload - -',left+82,h-10);if(d.labels?.length){x.fillText(d.labels[0],left,h-21);x.fillText(d.labels[d.labels.length-1],Math.max(left,w-95),h-21)}}
function renderDetails(rows){const el=$('details');if(!rows?.length){el.innerHTML='<tr><td colspan="5">Belum ada histori.</td></tr>';return}const r=rows.slice(-100).reverse();el.innerHTML=r.map(x=>`<tr><td>${x.time}</td><td>${bytes(x.rx)}</td><td>${bytes(x.tx)}</td><td>${speed(x.rx_bps)}</td><td>${speed(x.tx_bps)}</td></tr>`).join('')}
async function load(range=currentRange){currentRange=range;document.querySelectorAll('.range').forEach(b=>b.classList.toggle('active',b.dataset.range===range));try{const r=await fetch(api+'?username='+encodeURIComponent(user)+'&range='+range+'&t='+Date.now(),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Gagal mengambil histori');const m=d.meta||{};$('meta').textContent=[m.profile||'default',m.ip_address||'-',m.interface||'-',d.records+' records'].join(' • ');$('rx').textContent=bytes(d.latest_rx);$('tx').textContent=bytes(d.latest_tx);$('avgRx').textContent=speed(d.average_rx_bps);$('avgTx').textContent=speed(d.average_tx_bps);$('peakRx').textContent=speed(d.peak_rx_bps);$('peakTx').textContent=speed(d.peak_tx_bps);renderDetails(d.details);draw(d)}catch(e){$('meta').textContent=e.message;draw({});$('details').innerHTML='<tr><td colspan="5">Data belum tersedia.</td></tr>'}}
document.querySelectorAll('.range').forEach(b=>b.addEventListener('click',()=>load(b.dataset.range)));load();setInterval(()=>{if(document.visibilityState==='visible')load(currentRange)},10000);window.addEventListener('resize',()=>load(currentRange));
</script></body></html>